//! Emulation of the warp-level matrix instructions on Apple GPUs.
//!
//! AGX has no tensor cores, so `ldmatrix`, `stmatrix`, `movmatrix`,
//! `mma.sync` and `wmma` are computed by the 32 threads of the SIMD-group (a
//! warp) with SIMD-group shuffles and ordinary integer arithmetic. Each
//! variant becomes a call to a helper function named after it
//! (`helper_name`, for example `__zluda_ptx_impl_agx_mma_m16n8k16_f32_f16_f16_f32`),
//! whose LLVM IR is generated by `define_helpers` when the module is emitted.
//!
//! * The fragments have the layouts of the PTX ISA (as transcribed by the K
//!   semantics of PTX-formalization): thread `lane` holds the elements given
//!   by `position`, with `g = lane / 4` and `t = lane % 4`. Every layout is
//!   linear in `g` and `t`, which `Layout` checks for all 32 threads.
//! * `ldmatrix` and `stmatrix` shuffle the row addresses, and each thread loads
//!   or stores its own elements.
//! * `mma.sync` gathers the rows of A held by the thread's quad with quad
//!   shuffles and the columns of B with SIMD-group shuffles, then computes its
//!   elements of D. Floating point sums are exact: the products and C are
//!   added as integers in a fixed point accumulator anchored at the largest
//!   term (120 bits, 248 for `f64`), and the sum is rounded once to nearest
//!   even into the type of D, like the model of PTX-formalization. Terms more
//!   than that below the largest one only contribute a sticky bit.
//! * `wmma` fragments are tiles of `mma.sync` fragments (16x8, or 8x8 for
//!   8-row matrices): A is made of the A fragments of its row tiles, B of the
//!   B fragments of its column tiles, C and D of the C fragments of the tiles
//!   in row major order, repeated when the PTX ISA gives the fragment more
//!   registers (`f16` A and B). `wmma.mma` runs `mma.sync` on each tile.

use super::*;
use llvm_zluda::core::*;
use llvm_zluda::prelude::*;
use std::collections::{BTreeSet, HashMap};
use std::ffi::CStr;
use std::fmt::Write;

const AGX_PREFIX: &str = "agx_";

#[derive(Copy, Clone)]
enum Helper {
    LdMatrix(ast::LdMatrixDetails),
    StMatrix(ast::LdMatrixDetails),
    MovMatrix,
    Mma(ast::MmaDetails),
    WmmaLoad(ast::WmmaLoadStoreDetails),
    WmmaStore(ast::WmmaLoadStoreDetails),
    WmmaMma(ast::MmaDetails),
}

/// The name (without `__zluda_ptx_impl_`) of the helper function emulating
/// a matrix instruction on AGX, or `None` for other instructions.
pub(super) fn helper_name(instruction: &ast::Instruction<SpirvWord>) -> Option<String> {
    let helper = match instruction {
        ast::Instruction::LdMatrix { data, .. } => Helper::LdMatrix(*data),
        ast::Instruction::StMatrix { data, .. } => Helper::StMatrix(*data),
        ast::Instruction::MovMatrix { .. } => Helper::MovMatrix,
        ast::Instruction::Mma { data, .. } | ast::Instruction::MmaBlockScale { data, .. } => {
            Helper::Mma(*data)
        }
        ast::Instruction::WmmaLoad { data, .. } => Helper::WmmaLoad(*data),
        ast::Instruction::WmmaStore { data, .. } => Helper::WmmaStore(*data),
        ast::Instruction::WmmaMma { data, .. } => Helper::WmmaMma(*data),
        _ => return None,
    };
    Some(helper.name())
}

// ---------------------------------------------------------------- names

const SHAPES: [(&str, ast::MatrixShape); 4] = [
    ("m8n8", ast::MatrixShape::M8n8),
    ("m16n16", ast::MatrixShape::M16n16),
    ("m8n16", ast::MatrixShape::M8n16),
    ("m16n8", ast::MatrixShape::M16n8),
];
const FORMATS: [(&str, ast::LdMatrixFormat); 5] = [
    ("b16", ast::LdMatrixFormat::B16),
    ("b8", ast::LdMatrixFormat::B8),
    ("b6x16p32", ast::LdMatrixFormat::B6x16P32),
    ("b4x16p64", ast::LdMatrixFormat::B4x16P64),
    ("s4", ast::LdMatrixFormat::S4),
];
const NUMBERS: [(&str, ast::MatrixNumber); 3] = [
    ("x1", ast::MatrixNumber::X1),
    ("x2", ast::MatrixNumber::X2),
    ("x4", ast::MatrixNumber::X4),
];
const MATRICES: [(&str, ast::MmaMatrix); 4] = [
    ("a", ast::MmaMatrix::A),
    ("b", ast::MmaMatrix::B),
    ("c", ast::MmaMatrix::C),
    ("d", ast::MmaMatrix::D),
];
const SPACES: [(&str, ast::StateSpace); 3] = [
    ("global", ast::StateSpace::Global),
    ("shared", ast::StateSpace::Shared),
    ("generic", ast::StateSpace::Generic),
];
const LAYOUTS: [(&str, ast::MatrixLayout); 2] =
    [("row", ast::MatrixLayout::Row), ("col", ast::MatrixLayout::Col)];

fn name_of<T: PartialEq + Copy>(table: &[(&'static str, T)], value: T) -> &'static str {
    table.iter().find(|(_, v)| *v == value).unwrap().0
}

fn value_of<T: Copy>(table: &[(&'static str, T)], name: &str) -> Option<T> {
    table.iter().find(|(n, _)| *n == name).map(|(_, v)| *v)
}

fn mma_name(d: &ast::MmaDetails) -> String {
    let mut name = format!(
        "m{}n{}k{}_{}_{}_{}_{}",
        d.m,
        d.n,
        d.k,
        d.dtype.name(),
        d.atype.name(),
        d.btype.name(),
        d.ctype.name()
    );
    if d.satfinite {
        name.push_str("_satfinite");
    }
    match d.b1_op {
        Some(ast::MmaB1Op::Xor) => name.push_str("_xor"),
        Some(ast::MmaB1Op::And) => name.push_str("_and"),
        None => {}
    }
    if let Some(s) = d.block_scale {
        let stype = if s.ue4m3 { "ue4m3" } else { "ue8m0" };
        write!(
            name,
            "_bs{}{stype}_a{}{}_b{}{}",
            s.chunks, s.a_byte, s.a_thread, s.b_byte, s.b_thread
        )
        .unwrap();
    }
    name
}

fn parse_shape(shape: &str) -> Option<(u32, u32, u32)> {
    let (m, rest) = shape.strip_prefix('m')?.split_once('n')?;
    let (n, k) = rest.split_once('k')?;
    Some((m.parse().ok()?, n.parse().ok()?, k.parse().ok()?))
}

fn parse_mma(parts: &[&str]) -> Option<ast::MmaDetails> {
    let (m, n, k) = parse_shape(parts.first()?)?;
    let types = parts
        .get(1..5)?
        .iter()
        .map(|t| ast::MmaType::from_name(t))
        .collect::<Option<Vec<_>>>()?;
    let flags = &parts[5..];
    Some(ast::MmaDetails {
        m,
        n,
        k,
        alayout: ast::MatrixLayout::Row,
        blayout: ast::MatrixLayout::Col,
        dtype: types[0],
        atype: types[1],
        btype: types[2],
        ctype: types[3],
        satfinite: flags.contains(&"satfinite"),
        b1_op: if flags.contains(&"xor") {
            Some(ast::MmaB1Op::Xor)
        } else if flags.contains(&"and") {
            Some(ast::MmaB1Op::And)
        } else {
            None
        },
        block_scale: match flags {
            [.., bs, a, b] if bs.starts_with("bs") => {
                let digit = |s: &str, i: usize| s[i..i + 1].parse::<u32>().ok();
                Some(ast::MmaBlockScale {
                    chunks: digit(bs, 2)?,
                    ue4m3: bs.ends_with("ue4m3"),
                    a_byte: digit(a, 1)?,
                    a_thread: digit(a, 2)?,
                    b_byte: digit(b, 1)?,
                    b_thread: digit(b, 2)?,
                })
            }
            _ => None,
        },
    })
}

impl Helper {
    fn name(&self) -> String {
        let moves = |op: &str, d: &ast::LdMatrixDetails| {
            format!(
                "{AGX_PREFIX}{op}_{}_{}{}_{}",
                name_of(&SHAPES, d.shape),
                name_of(&NUMBERS, d.number),
                if d.transpose { "_trans" } else { "" },
                name_of(&FORMATS, d.format)
            )
        };
        let wmma = |op: &str, d: &ast::WmmaLoadStoreDetails| {
            format!(
                "{AGX_PREFIX}wmma_{op}_{}_{}_m{}n{}k{}_{}_{}",
                name_of(&MATRICES, d.matrix),
                name_of(&LAYOUTS, d.layout),
                d.m,
                d.n,
                d.k,
                d.type_.name(),
                name_of(&SPACES, d.state_space)
            )
        };
        match self {
            Helper::LdMatrix(d) => moves("ldmatrix", d),
            Helper::StMatrix(d) => moves("stmatrix", d),
            Helper::MovMatrix => format!("{AGX_PREFIX}movmatrix_m8n8_trans_b16"),
            Helper::Mma(d) => format!("{AGX_PREFIX}mma_{}", mma_name(d)),
            Helper::WmmaLoad(d) => wmma("load", d),
            Helper::WmmaStore(d) => wmma("store", d),
            Helper::WmmaMma(d) => format!("{AGX_PREFIX}wmma_mma_{}", mma_name(d)),
        }
    }

    fn from_name(name: &str) -> Option<Helper> {
        let parts = name.strip_prefix(AGX_PREFIX)?.split('_').collect::<Vec<_>>();
        match parts[..] {
            [op @ ("ldmatrix" | "stmatrix"), shape, number, ref rest @ ..] => {
                let (transpose, format) = match rest {
                    ["trans", format] => (true, *format),
                    [format] => (false, *format),
                    _ => return None,
                };
                let details = ast::LdMatrixDetails {
                    shape: value_of(&SHAPES, shape)?,
                    number: value_of(&NUMBERS, number)?,
                    transpose,
                    state_space: ast::StateSpace::Shared,
                    format: value_of(&FORMATS, format)?,
                };
                Some(if op == "ldmatrix" {
                    Helper::LdMatrix(details)
                } else {
                    Helper::StMatrix(details)
                })
            }
            ["movmatrix", ..] => Some(Helper::MovMatrix),
            ["mma", ref rest @ ..] => parse_mma(rest).map(Helper::Mma),
            ["wmma", "mma", ref rest @ ..] => parse_mma(rest).map(Helper::WmmaMma),
            ["wmma", op @ ("load" | "store"), matrix, layout, shape, type_, space] => {
                let (m, n, k) = parse_shape(shape)?;
                let details = ast::WmmaLoadStoreDetails {
                    matrix: value_of(&MATRICES, matrix)?,
                    layout: value_of(&LAYOUTS, layout)?,
                    m,
                    n,
                    k,
                    state_space: value_of(&SPACES, space)?,
                    type_: ast::MmaType::from_name(type_)?,
                };
                Some(if op == "load" {
                    Helper::WmmaLoad(details)
                } else {
                    Helper::WmmaStore(details)
                })
            }
            _ => None,
        }
    }
}

// ---------------------------------------------------------------- module

/// Defines the helper functions of the matrix instructions declared in
/// `module` (see `helper_name`) by linking their generated IR into it.
pub(super) fn define_helpers(
    context: &llvm_zluda::utils::Context,
    module: &llvm_zluda::utils::Module,
) -> Result<(), TranslateError> {
    let mut text = String::new();
    let mut declarations = BTreeSet::new();
    unsafe {
        let mut function = LLVMGetFirstFunction(module.get());
        while !function.is_null() {
            let mut len = 0;
            let name = LLVMGetValueName2(function, &mut len);
            let name = std::str::from_utf8(std::slice::from_raw_parts(name as *const u8, len))
                .map_err(|_| error_unreachable())?
                .to_string();
            let helper = name
                .strip_prefix(ZLUDA_PTX_PREFIX)
                .and_then(Helper::from_name);
            if let (Some(helper), true) = (helper, LLVMIsDeclaration(function) != 0) {
                let fn_type = LLVMGlobalGetValueType(function);
                let ret = type_name(LLVMGetReturnType(fn_type));
                let count = LLVMCountParamTypes(fn_type) as usize;
                let mut params = vec![ptr::null_mut(); count];
                LLVMGetParamTypes(fn_type, params.as_mut_ptr());
                let params = params.into_iter().map(|t| type_name(t)).collect::<Vec<_>>();
                text.push_str(&define(helper, &name, &ret, &params, &mut declarations)?);
            }
            function = LLVMGetNextFunction(function);
        }
    }
    if text.is_empty() {
        return Ok(());
    }
    text.push_str(DECLARATIONS);
    for declaration in declarations {
        text.push_str(&declaration);
        text.push('\n');
    }
    let helpers = llvm_zluda::utils::Module::try_from_ir(context, text.as_bytes(), c"agx_matrix")
        .map_err(|e| TranslateError::Unsupported(format!("AGX matrix helpers: {e}")))?;
    module
        .link(helpers)
        .map_err(|e| TranslateError::Unsupported(format!("AGX matrix helpers: {e}")))
}

use std::ptr;

unsafe fn type_name(type_: LLVMTypeRef) -> String {
    let text = LLVMPrintTypeToString(type_);
    let result = CStr::from_ptr(text).to_string_lossy().into_owned();
    LLVMDisposeMessage(text);
    result
}

const DECLARATIONS: &str = r#"
declare i32 @llvm.agx.thread.index.in.simdgroup()
declare i32 @llvm.agx.simd.shuffle.i32(i32, i32)
declare i32 @llvm.agx.quad.shuffle.i32(i32, i32)
declare i64 @__zluda_ptx_impl_agx_round_pack(i1, i64, i1, i32, i32, i32)
attributes #0 = { alwaysinline convergent nounwind }
"#;

fn define(
    helper: Helper,
    name: &str,
    ret: &str,
    params: &[String],
    declarations: &mut BTreeSet<String>,
) -> Result<String, TranslateError> {
    let mut ir = Ir::default();
    let args = params
        .iter()
        .enumerate()
        .map(|(i, t)| format!("{t} %p{i}"))
        .collect::<Vec<_>>()
        .join(", ");
    let lane = ir.def("call i32 @llvm.agx.thread.index.in.simdgroup()");
    let g = ir.def(&format!("lshr i32 {lane}, 2"));
    let t = ir.def(&format!("and i32 {lane}, 3"));
    let lane = Lane { g, t };
    let param = |i: usize| -> Result<(String, &String), TranslateError> {
        Ok((
            format!("%p{i}"),
            params.get(i).ok_or_else(|| todo("helper arguments"))?,
        ))
    };
    let result = match helper {
        Helper::LdMatrix(d) => {
            let (p, pt) = param(0)?;
            Some(ldmatrix(&mut ir, &lane, &d, &p, pt)?)
        }
        Helper::StMatrix(d) => {
            let (p, pt) = param(0)?;
            let (v, vt) = param(1)?;
            let regs = ir.unpack(&v, vt)?;
            stmatrix(&mut ir, &lane, &d, &p, pt, &regs)?;
            None
        }
        Helper::MovMatrix => {
            let (v, vt) = param(0)?;
            let src = ir.unpack(&v, vt)?;
            Some(vec![movmatrix(&mut ir, &lane, &src[0])])
        }
        Helper::Mma(d) => {
            let a = ir.unpack(&param(0)?.0, param(0)?.1)?;
            let b = ir.unpack(&param(1)?.0, param(1)?.1)?;
            let c = ir.unpack(&param(2)?.0, param(2)?.1)?;
            let scales = if d.block_scale.is_some() {
                Some((param(3)?.0, param(4)?.0))
            } else {
                None
            };
            Some(mma_tile(&mut ir, &lane, &d, &a, &b, &c, scales)?)
        }
        Helper::WmmaMma(d) => {
            let a = ir.unpack(&param(0)?.0, param(0)?.1)?;
            let b = ir.unpack(&param(1)?.0, param(1)?.1)?;
            let c = ir.unpack(&param(2)?.0, param(2)?.1)?;
            Some(wmma_mma(&mut ir, &lane, &d, &a, &b, &c)?)
        }
        Helper::WmmaLoad(d) => {
            let (p, pt) = param(0)?;
            let (s, _) = param(1)?;
            Some(wmma_load(&mut ir, &lane, &d, &p, pt, &s)?)
        }
        Helper::WmmaStore(d) => {
            let (p, pt) = param(0)?;
            let (v, vt) = param(1)?;
            let (s, _) = param(2)?;
            let regs = ir.unpack(&v, vt)?;
            wmma_store(&mut ir, &lane, &d, &p, pt, &regs, &s)?;
            None
        }
    };
    match result {
        Some(regs) => {
            let value = ir.pack(&regs, ret)?;
            ir.stmt(&format!("ret {ret} {value}"));
        }
        None => ir.stmt("ret void"),
    }
    declarations.extend(ir.declarations);
    Ok(format!("define {ret} @{name}({args}) #0 {{\n{}}}\n", ir.out))
}

fn todo(what: &str) -> TranslateError {
    TranslateError::Unsupported(format!("AGX matrix emulation: {what}"))
}

// ---------------------------------------------------------------- IR text

struct Ir {
    out: String,
    next: usize,
    // the current basic block
    block: String,
    // declarations of the intrinsics used
    declarations: BTreeSet<String>,
}

struct Lane {
    g: String,
    t: String,
}

// The integer type of a register or vector element type.
fn int_type(type_: &str) -> Result<&'static str, TranslateError> {
    Ok(match type_ {
        "i32" | "float" => "i32",
        "i64" | "double" => "i64",
        _ => return Err(todo("fragment type")),
    })
}

impl Default for Ir {
    fn default() -> Self {
        Ir {
            out: "entry:\n".to_string(),
            next: 0,
            block: "entry".to_string(),
            declarations: BTreeSet::new(),
        }
    }
}

impl Ir {
    fn label(&mut self, name: &str) {
        writeln!(self.out, "{name}:").unwrap();
        self.block = name.to_string();
    }

    fn def(&mut self, rhs: &str) -> String {
        self.next += 1;
        let name = format!("%v{}", self.next);
        writeln!(self.out, "  {name} = {rhs}").unwrap();
        name
    }

    fn stmt(&mut self, s: &str) {
        writeln!(self.out, "  {s}").unwrap();
    }

    fn op(&mut self, op: &str, ty: &str, a: &str, b: &str) -> String {
        self.def(&format!("{op} {ty} {a}, {b}"))
    }

    fn icmp(&mut self, pred: &str, ty: &str, a: &str, b: &str) -> String {
        self.def(&format!("icmp {pred} {ty} {a}, {b}"))
    }

    fn select(&mut self, c: &str, ty: &str, a: &str, b: &str) -> String {
        self.def(&format!("select i1 {c}, {ty} {a}, {ty} {b}"))
    }

    fn cast(&mut self, op: &str, from: &str, v: &str, to: &str) -> String {
        if from == to {
            return v.to_string();
        }
        self.def(&format!("{op} {from} {v} to {to}"))
    }

    fn intrinsic(&mut self, name: &str, ty: &str, args: &[&str]) -> String {
        let types = vec![ty; args.len()].join(", ");
        let args = args
            .iter()
            .map(|a| format!("{ty} {a}"))
            .collect::<Vec<_>>()
            .join(", ");
        self.declarations
            .insert(format!("declare {ty} @llvm.{name}.{ty}({types})"));
        self.def(&format!("call {ty} @llvm.{name}.{ty}({args})"))
    }

    /// The registers of a fragment argument, as i32 or i64 values.
    fn unpack(&mut self, v: &str, type_: &str) -> Result<Vec<String>, TranslateError> {
        if let Some(inner) = type_.strip_prefix('<').and_then(|s| s.strip_suffix('>')) {
            let (count, element) = inner.split_once(" x ").ok_or_else(|| todo("vector"))?;
            let count: usize = count.parse().map_err(|_| todo("vector"))?;
            let int = int_type(element)?;
            Ok((0..count)
                .map(|i| {
                    let e = self.def(&format!("extractelement {type_} {v}, i32 {i}"));
                    self.cast("bitcast", element, &e, int)
                })
                .collect())
        } else {
            let int = int_type(type_)?;
            Ok(vec![self.cast("bitcast", type_, v, int)])
        }
    }

    fn pack(&mut self, regs: &[String], type_: &str) -> Result<String, TranslateError> {
        if let Some(inner) = type_.strip_prefix('<').and_then(|s| s.strip_suffix('>')) {
            let (count, element) = inner.split_once(" x ").ok_or_else(|| todo("vector"))?;
            let count: usize = count.parse().map_err(|_| todo("vector"))?;
            if count != regs.len() {
                return Err(todo("fragment size"));
            }
            let int = int_type(element)?;
            let mut value = "poison".to_string();
            for (i, r) in regs.iter().enumerate() {
                let e = self.cast("bitcast", int, r, element);
                value = self.def(&format!("insertelement {type_} {value}, {element} {e}, i32 {i}"));
            }
            Ok(value)
        } else {
            let int = int_type(type_)?;
            Ok(self.cast("bitcast", int, &regs[0], type_))
        }
    }

    /// `v` of thread `lane` of the SIMD-group (or, with `quad`, of the quad).
    fn shuffle(&mut self, v: &str, bits: u32, lane: &str, quad: bool) -> String {
        let f = if quad { "quad" } else { "simd" };
        if bits == 32 {
            return self.def(&format!("call i32 @llvm.agx.{f}.shuffle.i32(i32 {v}, i32 {lane})"));
        }
        let lo = self.cast("trunc", "i64", v, "i32");
        let hi0 = self.op("lshr", "i64", v, "32");
        let hi = self.cast("trunc", "i64", &hi0, "i32");
        let lo = self.def(&format!("call i32 @llvm.agx.{f}.shuffle.i32(i32 {lo}, i32 {lane})"));
        let hi = self.def(&format!("call i32 @llvm.agx.{f}.shuffle.i32(i32 {hi}, i32 {lane})"));
        let lo = self.cast("zext", "i32", &lo, "i64");
        let hi = self.cast("zext", "i32", &hi, "i64");
        let hi = self.op("shl", "i64", &hi, "32");
        self.op("or", "i64", &lo, &hi)
    }

    // a * x + b * y + c, as an i32 (x and y are i32 values)
    fn linear(&mut self, a: u32, x: &str, b: u32, y: &str, c: u32) -> String {
        let mut acc = c.to_string();
        for (k, v) in [(a, x), (b, y)] {
            if k != 0 {
                let p = self.op("mul", "i32", v, &k.to_string());
                acc = self.op("add", "i32", &acc, &p);
            }
        }
        acc
    }

    // The address `base + offset` (i64 offset in bytes) as a pointer of type `ptr_type`.
    fn address(&mut self, base: &str, offset: &str, ptr_type: &str) -> String {
        let a = self.op("add", "i64", base, offset);
        self.def(&format!("inttoptr i64 {a} to {ptr_type}"))
    }

    fn load(&mut self, ty: &str, ptr: &str, ptr_type: &str, align: u32) -> String {
        self.def(&format!("load {ty}, {ptr_type} {ptr}, align {align}"))
    }

    fn store(&mut self, ty: &str, v: &str, ptr: &str, ptr_type: &str, align: u32) {
        self.stmt(&format!("store {ty} {v}, {ptr_type} {ptr}, align {align}"));
    }
}

// ---------------------------------------------------------------- ldmatrix, stmatrix, movmatrix

// The address of the row given by thread `lane` (an i32 value).
fn row_address(ir: &mut Ir, base: &str, lane: &str) -> String {
    ir.shuffle(base, 64, lane, false)
}

fn pointer_bits(ir: &mut Ir, p: &str, ptr_type: &str) -> String {
    ir.def(&format!("ptrtoint {ptr_type} {p} to i64"))
}

// A 16-byte (8-byte with `bytes == 8`) row of a matrix, as an i128.
fn load_row(ir: &mut Ir, row: &str, ptr_type: &str, bytes: u32) -> String {
    let mut value = "0".to_string();
    for w in 0..bytes / 4 {
        let a = ir.address(row, &(4 * w).to_string(), ptr_type);
        let x = ir.load("i32", &a, ptr_type, 4);
        let x = ir.cast("zext", "i32", &x, "i128");
        let x = ir.op("shl", "i128", &x, &(32 * w).to_string());
        value = ir.op("or", "i128", &value, &x);
    }
    value
}

// Element `column` (an i32 value) of a row, expanded to 8 bits.
fn row_element(ir: &mut Ir, format: ast::LdMatrixFormat, row: &str, column: &str) -> String {
    let (width, mask) = match format {
        ast::LdMatrixFormat::B6x16P32 => (6, 63),
        ast::LdMatrixFormat::B4x16P64 | ast::LdMatrixFormat::S4 => (4, 15),
        _ => (8, 255),
    };
    let shift = ir.op("mul", "i32", column, &width.to_string());
    let shift = ir.cast("zext", "i32", &shift, "i128");
    let x = ir.op("lshr", "i128", row, &shift);
    let x = ir.cast("trunc", "i128", &x, "i32");
    let x = ir.op("and", "i32", &x, &mask.to_string());
    match format {
        // the central bits of the container
        ast::LdMatrixFormat::B4x16P64 => ir.op("shl", "i32", &x, "2"),
        // sign extended
        ast::LdMatrixFormat::S4 => {
            let s = ir.op("shl", "i32", &x, "28");
            let s = ir.op("ashr", "i32", &s, "28");
            ir.op("and", "i32", &s, "255")
        }
        _ => x,
    }
}

fn bytes_to_register(ir: &mut Ir, bytes: &[String]) -> String {
    let mut value = "0".to_string();
    for (b, x) in bytes.iter().enumerate() {
        let x = ir.op("shl", "i32", x, &(8 * b).to_string());
        value = ir.op("or", "i32", &value, &x);
    }
    value
}

// Matrix i of ldmatrix has its row r addressed by thread 8i + r (16i + r for
// m16n16). m8n8: thread (g, t) holds (g, 2t), (g, 2t + 1) of each matrix, or
// (2t, g), (2t + 1, g) with .trans. m8n16: elements 4t..4t+3 of row g.
// m16n16 (.trans): register 2i holds rows 4t..4t+3 of column g, register
// 2i + 1 of column g + 8.
fn ldmatrix(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::LdMatrixDetails,
    p: &str,
    ptr_type: &str,
) -> Result<Vec<String>, TranslateError> {
    let base = pointer_bits(ir, p, ptr_type);
    let (g, t) = (&lane.g.clone(), &lane.t.clone());
    let mut regs = Vec::new();
    for i in 0..d.number.get() as u32 {
        match d.shape {
            ast::MatrixShape::M8n8 if !d.transpose => {
                let l = ir.linear(1, g, 0, t, 8 * i);
                let row = row_address(ir, &base, &l);
                let off = ir.op("mul", "i32", t, "4");
                let off = ir.cast("zext", "i32", &off, "i64");
                let a = ir.address(&row, &off, ptr_type);
                regs.push(ir.load("i32", &a, ptr_type, 4));
            }
            ast::MatrixShape::M8n8 => {
                let off = ir.op("mul", "i32", g, "2");
                let off = ir.cast("zext", "i32", &off, "i64");
                let mut halves = Vec::new();
                for h in 0..2 {
                    let l = ir.linear(0, g, 2, t, 8 * i + h);
                    let row = row_address(ir, &base, &l);
                    let a = ir.address(&row, &off, ptr_type);
                    let x = ir.load("i16", &a, ptr_type, 2);
                    halves.push(ir.cast("zext", "i16", &x, "i32"));
                }
                let hi = ir.op("shl", "i32", &halves[1], "16");
                regs.push(ir.op("or", "i32", &halves[0], &hi));
            }
            ast::MatrixShape::M8n16 => {
                let l = ir.linear(1, g, 0, t, 8 * i);
                let row = row_address(ir, &base, &l);
                let bytes = if d.format == ast::LdMatrixFormat::S4 { 8 } else { 16 };
                let row = load_row(ir, &row, ptr_type, bytes);
                let elements = (0..4)
                    .map(|b| {
                        let c = ir.linear(0, g, 4, t, b);
                        row_element(ir, d.format, &row, &c)
                    })
                    .collect::<Vec<_>>();
                regs.push(bytes_to_register(ir, &elements));
            }
            ast::MatrixShape::M16n16 => {
                let rows = (0..4)
                    .map(|b| {
                        let l = ir.linear(0, g, 4, t, 16 * i + b);
                        let row = row_address(ir, &base, &l);
                        load_row(ir, &row, ptr_type, 16)
                    })
                    .collect::<Vec<_>>();
                for column_offset in [0, 8] {
                    let c = ir.linear(1, g, 0, t, column_offset);
                    let elements = rows
                        .iter()
                        .map(|row| row_element(ir, d.format, row, &c))
                        .collect::<Vec<_>>();
                    regs.push(bytes_to_register(ir, &elements));
                }
            }
            ast::MatrixShape::M16n8 => return Err(todo("ldmatrix shape")),
        }
    }
    Ok(regs)
}

// The inverse of ldmatrix: each thread stores its elements into the rows
// addressed by the other threads. m16n8 (.b8, .trans): register i holds
// X[g][2t], X[g][2t + 1], X[g + 8][2t], X[g + 8][2t + 1] of a 16x8 matrix X,
// whose column n is the row addressed by thread 8i + n.
fn stmatrix(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::LdMatrixDetails,
    p: &str,
    ptr_type: &str,
    regs: &[String],
) -> Result<(), TranslateError> {
    let base = pointer_bits(ir, p, ptr_type);
    let (g, t) = (&lane.g.clone(), &lane.t.clone());
    if d.shape == ast::MatrixShape::M16n8 {
        return stmatrix_m16n8(ir, lane, d, p, ptr_type, regs);
    }
    for i in 0..d.number.get() as u32 {
        let v = regs.get(i as usize).ok_or_else(|| todo("stmatrix registers"))?;
        match d.shape {
            ast::MatrixShape::M8n8 if !d.transpose => {
                let l = ir.linear(1, g, 0, t, 8 * i);
                let row = row_address(ir, &base, &l);
                let off = ir.op("mul", "i32", t, "4");
                let off = ir.cast("zext", "i32", &off, "i64");
                let a = ir.address(&row, &off, ptr_type);
                ir.store("i32", v, &a, ptr_type, 4);
            }
            ast::MatrixShape::M8n8 => {
                let off = ir.op("mul", "i32", g, "2");
                let off = ir.cast("zext", "i32", &off, "i64");
                for h in 0..2 {
                    let l = ir.linear(0, g, 2, t, 8 * i + h);
                    let row = row_address(ir, &base, &l);
                    let a = ir.address(&row, &off, ptr_type);
                    let x = ir.op("lshr", "i32", v, &(16 * h).to_string());
                    let x = ir.cast("trunc", "i32", &x, "i16");
                    ir.store("i16", &x, &a, ptr_type, 2);
                }
            }
            _ => return Err(todo("stmatrix shape")),
        }
    }
    Ok(())
}

// stmatrix.m16n8: thread 8i + n (n < 8) gathers column n of matrix i, X[m][n]
// being byte 2 * (m / 8) + n % 2 of register i of thread 4 * (m % 8) + n / 2,
// and stores it as its 16-byte row.
fn stmatrix_m16n8(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::LdMatrixDetails,
    p: &str,
    ptr_type: &str,
    regs: &[String],
) -> Result<(), TranslateError> {
    let number = d.number.get() as usize;
    let regs = regs.get(..number).ok_or_else(|| todo("stmatrix registers"))?;
    // this thread's matrix i and column n
    let l = ir.linear(4, &lane.g, 1, &lane.t, 0);
    let i = ir.op("lshr", "i32", &l, "3");
    let n = ir.op("and", "i32", &l, "7");
    let n_half = ir.op("lshr", "i32", &n, "1");
    let n_odd = ir.op("and", "i32", &n, "1");
    let mut words = vec!["0".to_string(); 4];
    for m in 0..16u32 {
        let source = ir.op("add", "i32", &n_half, &(4 * (m % 8)).to_string());
        let mut value = "0".to_string();
        for (j, r) in regs.iter().enumerate() {
            let x = ir.shuffle(r, 32, &source, false);
            let mine = ir.icmp("eq", "i32", &i, &j.to_string());
            value = ir.select(&mine, "i32", &x, &value);
        }
        let byte = ir.op("add", "i32", &n_odd, &(2 * (m / 8)).to_string());
        let shift = ir.op("mul", "i32", &byte, "8");
        let x = ir.op("lshr", "i32", &value, &shift);
        let x = ir.op("and", "i32", &x, "255");
        let x = ir.op("shl", "i32", &x, &(8 * (m % 4)).to_string());
        let w = (m / 4) as usize;
        words[w] = ir.op("or", "i32", &words[w], &x);
    }
    let base = pointer_bits(ir, p, ptr_type);
    let l = ir.linear(4, &lane.g, 1, &lane.t, 0);
    let stores = ir.icmp("ult", "i32", &l, &(8 * number).to_string());
    ir.stmt(&format!("br i1 {stores}, label %store, label %done"));
    ir.label("store");
    for (w, word) in words.iter().enumerate() {
        let a = ir.address(&base, &(4 * w).to_string(), ptr_type);
        ir.store("i32", word, &a, ptr_type, 4);
    }
    ir.stmt("br label %done");
    ir.label("done");
    Ok(())
}

// Thread (g, t) receives elements (2t, g) and (2t + 1, g) of the source
// matrix, whose element (r, c) is half c % 2 of the register of thread
// 4r + c / 2.
fn movmatrix(ir: &mut Ir, lane: &Lane, src: &str) -> String {
    let (g, t) = (lane.g.clone(), lane.t.clone());
    let g2 = ir.op("lshr", "i32", &g, "1");
    let shift = ir.op("and", "i32", &g, "1");
    let shift = ir.op("mul", "i32", &shift, "16");
    let mut halves = Vec::new();
    for h in 0..2 {
        let l = ir.linear(8, &t, 1, &g2, 4 * h);
        let x = ir.shuffle(src, 32, &l, false);
        let x = ir.op("lshr", "i32", &x, &shift);
        halves.push(ir.op("and", "i32", &x, "65535"));
    }
    let hi = ir.op("shl", "i32", &halves[1], "16");
    ir.op("or", "i32", &halves[0], &hi)
}

// ---------------------------------------------------------------- fragment layouts

/// (row, column) of element `i` of the fragment of thread `lane`, for a
/// matrix of an m x 8 x k `mma.sync` tile with elements of `bits` bits.
fn position(matrix: ast::MmaMatrix, m: u32, k: u32, bits: u32, lane: u32, i: u32) -> Option<(u32, u32)> {
    let (g, t) = (lane / 4, lane % 4);
    Some(match matrix {
        ast::MmaMatrix::A => match (bits, m, k) {
            (16, 16, 16) => (g + 8 * ((i / 2) % 2), 2 * t + i % 2 + 8 * (i / 4)),
            (16, 16, 8) => (g + 8 * (i / 2), 2 * t + i % 2),
            // the rows 0 to 7 of m16n8k16 (wmma m8n32k16)
            (16, 8, 16) => (g, 2 * t + i % 2 + 8 * (i / 2)),
            (32, 16, 8) => (g + 8 * (i % 2), t + 4 * (i / 2)),
            (32, 16, 4) => (g + 8 * i, t),
            (64, 8, 4) => (g, t),
            (64, 16, 4) => (g + 8 * i, t),
            (64, 16, 8) | (64, 16, 16) => (g + 8 * (i % 2), t + 4 * (i / 2)),
            (8, 8, 16) => (g, 4 * t + i),
            (8, 16, 16) => (g + 8 * (i / 4), 4 * t + i % 4),
            (8, 16, 32) => (g + 8 * ((i / 4) % 2), 4 * t + i % 4 + 16 * (i / 8)),
            (4, 8, 32) => (g, 8 * t + i),
            (4, 16, 32) => (g + 8 * (i / 8), 8 * t + i % 8),
            (4, 16, 64) => (g + 8 * ((i / 8) % 2), 8 * t + i % 8 + 32 * (i / 16)),
            (1, 8, 128) => (g, 32 * t + i),
            (1, 16, 128) => (g + 8 * (i / 32), 32 * t + i % 32),
            (1, 16, 256) => (g + 8 * ((i / 32) % 2), 32 * t + i % 32 + 128 * (i / 64)),
            _ => return None,
        },
        ast::MmaMatrix::B => match (bits, k) {
            (16, 16) => (2 * t + i % 2 + 8 * (i / 2), g),
            (16, 8) => (2 * t + i, g),
            (32, 4 | 8) | (64, 4 | 8 | 16) => (t + 4 * i, g),
            (8, 16) => (4 * t + i, g),
            (8, 32) => (4 * t + i % 4 + 16 * (i / 4), g),
            (4, 32) => (8 * t + i, g),
            (4, 64) => (8 * t + i % 8 + 32 * (i / 8), g),
            (1, 128) => (32 * t + i, g),
            (1, 256) => (32 * t + i % 32 + 128 * (i / 32), g),
            _ => return None,
        },
        ast::MmaMatrix::C | ast::MmaMatrix::D => {
            if m == 8 {
                (g, 2 * t + i)
            } else {
                (g + 8 * (i / 2), 2 * t + i % 2)
            }
        }
    })
}

/// A fragment layout: element i of thread (g, t) is at row
/// `rg * g + rt * t + row[i]`, column `cg * g + ct * t + col[i]`.
struct Layout {
    rg: u32,
    rt: u32,
    cg: u32,
    ct: u32,
    row: Vec<u32>,
    col: Vec<u32>,
}

impl Layout {
    fn new(matrix: ast::MmaMatrix, m: u32, k: u32, bits: u32, count: u32) -> Result<Self, TranslateError> {
        let pos = |lane, i| position(matrix, m, k, bits, lane, i).ok_or_else(|| todo("mma shape"));
        let mut layout = Layout {
            rg: 0,
            rt: 0,
            cg: 0,
            ct: 0,
            row: Vec::new(),
            col: Vec::new(),
        };
        for i in 0..count {
            let (r0, c0) = pos(0, i)?;
            let (r1, c1) = pos(1, i)?;
            let (r4, c4) = pos(4, i)?;
            if i == 0 {
                (layout.rt, layout.ct, layout.rg, layout.cg) = (r1 - r0, c1 - c0, r4 - r0, c4 - c0);
            }
            if (r1 - r0, c1 - c0, r4 - r0, c4 - c0) != (layout.rt, layout.ct, layout.rg, layout.cg) {
                return Err(todo("non-linear fragment layout"));
            }
            layout.row.push(r0);
            layout.col.push(c0);
        }
        for lane in 0..32 {
            let (g, t) = (lane / 4, lane % 4);
            for i in 0..count as usize {
                let expected = (
                    layout.rg * g + layout.rt * t + layout.row[i],
                    layout.cg * g + layout.ct * t + layout.col[i],
                );
                if pos(lane, i as u32)? != expected {
                    return Err(todo("non-linear fragment layout"));
                }
            }
        }
        Ok(layout)
    }
}

// Element `i` of a fragment of `bits`-bit elements in `regs`, zero extended
// to the register type.
fn fragment_element(ir: &mut Ir, regs: &[String], register_bits: u32, bits: u32, i: u32) -> Result<String, TranslateError> {
    let per = register_bits / bits;
    let r = regs.get((i / per) as usize).ok_or_else(|| todo("fragment size"))?;
    if per == 1 {
        return Ok(r.clone());
    }
    let ty = if register_bits == 64 { "i64" } else { "i32" };
    let x = ir.op("lshr", ty, r, &((i % per) * bits).to_string());
    Ok(ir.op("and", ty, &x, &((1u64 << bits) - 1).to_string()))
}

fn register_bits(type_: ast::MmaType) -> u32 {
    if type_ == ast::MmaType::F64 {
        64
    } else {
        32
    }
}

// ---------------------------------------------------------------- mma

/// One `mma.sync` tile (m x 8 x k, m = 8 or 16): the registers of D from
/// those of A, B and C.
fn mma_tile(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::MmaDetails,
    a: &[String],
    b: &[String],
    c: &[String],
    scales: Option<(String, String)>,
) -> Result<Vec<String>, TranslateError> {
    use ast::MmaMatrix::*;
    let (m, k) = (d.m, d.k);
    if d.n != 8 || (m != 8 && m != 16) {
        return Err(todo("mma shape"));
    }
    let ab_bits = d.atype.bits();
    let ab_reg_bits = register_bits(d.atype);
    let (na, nb, nc) = (m * k / 32, k * 8 / 32, m * 8 / 32);
    let la = Layout::new(A, m, k, ab_bits, na)?;
    let lb = Layout::new(B, m, k, ab_bits, nb)?;
    let lc = Layout::new(C, m, k, ab_bits, nc)?;
    if (la.rg, la.rt, la.cg) != (1, 0, 0)
        || (lb.rg, lb.cg, lb.ct) != (0, 1, 0)
        || lb.col.iter().any(|c| *c != 0)
        || (lc.rg, lc.rt, lc.cg, lc.ct) != (1, 0, 0, 2)
    {
        return Err(todo("fragment layout"));
    }
    // A: row g + 8h of the thread's quad, B: column 2t + e of quad 2t + e.
    let ab_ty = if ab_reg_bits == 64 { "i64" } else { "i32" };
    let mut shuffled: HashMap<(u32, u32, u32), String> = HashMap::new();
    let mut a_rows = vec![vec![None; k as usize]; (m / 8) as usize];
    let mut b_cols = vec![vec![None; k as usize]; 2];
    let per = ab_reg_bits / ab_bits;
    for source in 0..4u32 {
        for i in 0..na {
            let (h, kk) = (la.row[i as usize] / 8, la.ct * source + la.col[i as usize]);
            a_rows[h as usize][kk as usize] = Some((source, i));
        }
        for i in 0..nb {
            let kk = lb.rt * source + lb.row[i as usize];
            for e in 0..2 {
                b_cols[e][kk as usize] = Some((source, i));
            }
        }
    }
    let mut get = |ir: &mut Ir, which: u32, e: u32, source: u32, i: u32| -> Result<String, TranslateError> {
        let reg = i / per;
        let key = (which * 2 + e, source, reg);
        if !shuffled.contains_key(&key) {
            let v = if which == 0 {
                let r = a.get(reg as usize).ok_or_else(|| todo("fragment size"))?;
                ir.shuffle(r, ab_reg_bits, &source.to_string(), true)
            } else {
                let r = b.get(reg as usize).ok_or_else(|| todo("fragment size"))?;
                let l = ir.linear(0, &lane.g, 8, &lane.t, 4 * e + source);
                ir.shuffle(r, ab_reg_bits, &l, false)
            };
            shuffled.insert(key, v);
        }
        Ok(shuffled[&key].clone())
    };
    // The elements (raw bits) or, for .b1, 32-bit words along k.
    let word = d.atype == ast::MmaType::B1;
    let mut gather = |ir: &mut Ir, which: u32, index: u32| -> Result<Vec<String>, TranslateError> {
        let entries = if which == 0 { &a_rows[index as usize] } else { &b_cols[index as usize] };
        let mut values = Vec::new();
        if word {
            for chunk in 0..k / 32 {
                let (source, i) = entries[(32 * chunk) as usize].ok_or_else(|| todo("layout"))?;
                for j in 0..32 {
                    if entries[(32 * chunk + j) as usize] != Some((source, i + j)) || (i + j) / 32 != i / 32 || i % 32 != 0 {
                        return Err(todo("b1 layout"));
                    }
                }
                let e = if which == 0 { 0 } else { index };
                values.push(get(ir, which, e, source, i)?);
            }
        } else {
            for kk in 0..k as usize {
                let (source, i) = entries[kk].ok_or_else(|| todo("layout"))?;
                let e = if which == 0 { 0 } else { index };
                let r = get(ir, which, e, source, i)?;
                values.push(fragment_element(ir, &[r], ab_reg_bits, ab_bits, i % per)?);
            }
        }
        Ok(values)
    };
    let a_vals = (0..m / 8).map(|h| gather(ir, 0, h)).collect::<Result<Vec<_>, _>>()?;
    let b_vals = (0..2).map(|e| gather(ir, 1, e)).collect::<Result<Vec<_>, _>>()?;
    let _ = ab_ty;
    let c_bits = d.ctype.bits();
    let d_bits = d.dtype.bits();
    let mut d_elements = Vec::new();
    if d.atype == ast::MmaType::F64 {
        d_elements = f64_elements_loop(ir, d, &lc, &a_vals, &b_vals, c)?;
    }
    for j in 0..nc {
        if d.atype == ast::MmaType::F64 {
            break;
        }
        let (h, e) = (lc.row[j as usize] / 8, lc.col[j as usize]);
        let c_elem = fragment_element(ir, c, register_bits(d.ctype), c_bits, j)?;
        let av = &a_vals[h as usize];
        let bv = &b_vals[e as usize];
        let value = if let (Some(scale), Some((sa, sb))) = (d.block_scale, &scales) {
            let factors = block_scales(ir, lane, &scale, sa, sb, h, e);
            let (sa, sb) = (factors.0, factors.1);
            let block = d.k / scale.chunks;
            let mut terms = vec![decode(ir, d.ctype, &c_elem, "i32")?];
            for (kk, (x, y)) in av.iter().zip(bv).enumerate() {
                let x = decode(ir, d.atype, x, "i32")?;
                let y = decode(ir, d.btype, y, "i32")?;
                let p = product(ir, &x, &y);
                let chunk = kk / block as usize;
                let s = product(ir, &sa[chunk], &sb[chunk]);
                terms.push(product(ir, &p, &s));
            }
            exact_sum(ir, &terms, d.dtype)?
        } else if d.atype.is_float() {
            float_dot(ir, d, av, bv, &c_elem)?
        } else if word {
            b1_dot(ir, d, av, bv, &c_elem)
        } else {
            integer_dot(ir, d, av, bv, &c_elem)
        };
        d_elements.push(value);
    }
    // pack D
    let d_reg_bits = register_bits(d.dtype);
    let d_ty = if d_reg_bits == 64 { "i64" } else { "i32" };
    let per_d = d_reg_bits / d_bits;
    let mut regs = Vec::new();
    for chunk in d_elements.chunks(per_d as usize) {
        let mut value = "0".to_string();
        for (s, x) in chunk.iter().enumerate() {
            let x = if per_d > 1 {
                let x = ir.op("and", d_ty, x, &((1u64 << d_bits) - 1).to_string());
                ir.op("shl", d_ty, &x, &(s as u32 * d_bits).to_string())
            } else {
                x.clone()
            };
            value = ir.op("or", d_ty, &value, &x);
        }
        regs.push(value);
    }
    Ok(regs)
}

// The elements of D of an f64 mma, computed in a loop over the elements:
// unrolled, the exact sums of the elements take more registers than the
// hardware has.
fn f64_elements_loop(
    ir: &mut Ir,
    d: &ast::MmaDetails,
    lc: &Layout,
    a: &[Vec<String>],
    b: &[Vec<String>],
    c: &[String],
) -> Result<Vec<String>, TranslateError> {
    let k = d.k as usize;
    let nc = lc.row.len();
    for j in 0..nc {
        let (h, e) = if d.m == 16 { (j / 2, j % 2) } else { (0, j) };
        if (lc.row[j] / 8, lc.col[j]) != (h as u32, e as u32) {
            return Err(todo("f64 accumulator layout"));
        }
    }
    // value number j of the list
    let pick = |ir: &mut Ir, values: &[String], j: &str| {
        let mut result = values[0].clone();
        for (i, v) in values.iter().enumerate().skip(1) {
            let is = ir.icmp("eq", "i32", j, &i.to_string());
            result = ir.select(&is, "i64", v, &result);
        }
        result
    };
    let id = ir.next;
    let (head, exit) = (format!("f64_loop{id}"), format!("f64_done{id}"));
    let before = ir.block.clone();
    ir.stmt(&format!("br label %{head}"));
    ir.label(&head);
    let next = format!("%f64_next{id}");
    let j = ir.def(&format!("phi i32 [ 0, %{before} ], [ {next}, %{head} ]"));
    // the elements of D computed so far, carried by the loop
    let results = (0..nc).map(|i| format!("%f64_d{id}_{i}")).collect::<Vec<_>>();
    let previous = (0..nc)
        .map(|i| ir.def(&format!("phi i64 [ 0, %{before} ], [ {}, %{head} ]", results[i])))
        .collect::<Vec<_>>();
    let (h, e) = if d.m == 16 {
        (ir.op("lshr", "i32", &j, "1"), ir.op("and", "i32", &j, "1"))
    } else {
        ("0".to_string(), j.clone())
    };
    let mut av = Vec::new();
    let mut bv = Vec::new();
    for kk in 0..k {
        let column = a.iter().map(|row| row[kk].clone()).collect::<Vec<_>>();
        av.push(pick(ir, &column, &h));
        let row = b.iter().map(|column| column[kk].clone()).collect::<Vec<_>>();
        bv.push(pick(ir, &row, &e));
    }
    let ce = pick(ir, c.get(..nc).ok_or_else(|| todo("fragment size"))?, &j);
    let value = float_dot(ir, d, &av, &bv, &ce)?;
    for i in 0..nc {
        let is = ir.icmp("eq", "i32", &j, &i.to_string());
        ir.stmt(&format!(
            "{} = select i1 {is}, i64 {value}, i64 {}",
            results[i], previous[i]
        ));
    }
    ir.stmt(&format!("{next} = add i32 {j}, 1"));
    let more = ir.icmp("ult", "i32", &next, &nc.to_string());
    ir.stmt(&format!("br i1 {more}, label %{head}, label %{exit}"));
    ir.label(&exit);
    Ok(results)
}

// The scale factors of block scaled mma for row g + 8h of A and column
// 2t + e of B: those of A are in the scale register of thread 2 * a_thread +
// h of the quad, those of B of thread 4 * (2t + e) + b_thread.
fn block_scales(
    ir: &mut Ir,
    lane: &Lane,
    scale: &ast::MmaBlockScale,
    sa: &str,
    sb: &str,
    h: u32,
    e: u32,
) -> (Vec<Term>, Vec<Term>) {
    let ra = ir.shuffle(sa, 32, &(2 * scale.a_thread + h).to_string(), true);
    let l = ir.linear(0, &lane.g, 8, &lane.t, 4 * e + scale.b_thread);
    let rb = ir.shuffle(sb, 32, &l, false);
    let factors = |ir: &mut Ir, r: &str, byte: u32| {
        (0..scale.chunks)
            .map(|j| {
                let x = ir.op("lshr", "i32", r, &(8 * (byte + j)).to_string());
                let x = ir.op("and", "i32", &x, "255");
                scale_factor(ir, &x, scale.ue4m3)
            })
            .collect::<Vec<_>>()
    };
    (factors(ir, &ra, scale.a_byte), factors(ir, &rb, scale.b_byte))
}

// A scale factor: ue8m0 is 2^(x - 127); ue4m3 an unsigned e4m3 (as in
// PTX-formalization, the NaN encodings are not special).
fn scale_factor(ir: &mut Ir, x: &str, ue4m3: bool) -> Term {
    let (mantissa, exponent, width) = if ue4m3 {
        let m = ir.op("and", "i32", x, "7");
        let e = ir.op("lshr", "i32", x, "3");
        let e_zero = ir.icmp("eq", "i32", &e, "0");
        let hidden = ir.op("or", "i32", &m, "8");
        let m = ir.select(&e_zero, "i32", &m, &hidden);
        let e = ir.select(&e_zero, "i32", "1", &e);
        (ir.cast("zext", "i32", &m, "i64"), ir.op("sub", "i32", &e, "10"), 4)
    } else {
        ("1".to_string(), ir.op("sub", "i32", x, "127"), 1)
    };
    let zero = ir.icmp("eq", "i64", &mantissa, "0");
    Term {
        sign: "false".to_string(),
        mantissa,
        mantissa_type: "i64",
        exponent,
        width,
        nan: "false".to_string(),
        inf: "false".to_string(),
        zero,
    }
}

// Sign or zero extension of a `bits`-bit integer element to i32.
fn extend(ir: &mut Ir, x: &str, bits: u32, signed: bool) -> String {
    if !signed || bits == 32 {
        return x.to_string();
    }
    let s = ir.op("shl", "i32", x, &(32 - bits).to_string());
    ir.op("ashr", "i32", &s, &(32 - bits).to_string())
}

fn integer_dot(ir: &mut Ir, d: &ast::MmaDetails, a: &[String], b: &[String], c: &str) -> String {
    let bits = d.atype.bits();
    let signed = |t| matches!(t, ast::MmaType::S8 | ast::MmaType::S4);
    let products = a
        .iter()
        .zip(b)
        .map(|(x, y)| {
            let x = extend(ir, x, bits, signed(d.atype));
            let y = extend(ir, y, bits, signed(d.btype));
            ir.op("mul", "i32", &x, &y)
        })
        .collect::<Vec<_>>();
    if !d.satfinite {
        let mut acc = c.to_string();
        for p in products {
            acc = ir.op("add", "i32", &acc, &p);
        }
        return acc;
    }
    // exact sum, clamped to the s32 range
    let mut acc = ir.cast("sext", "i32", c, "i64");
    for p in products {
        let p = ir.cast("sext", "i32", &p, "i64");
        acc = ir.op("add", "i64", &acc, &p);
    }
    let acc = ir.intrinsic("smin", "i64", &[&acc, "2147483647"]);
    let acc = ir.intrinsic("smax", "i64", &[&acc, "-2147483648"]);
    ir.cast("trunc", "i64", &acc, "i32")
}

fn b1_dot(ir: &mut Ir, d: &ast::MmaDetails, a: &[String], b: &[String], c: &str) -> String {
    let op = if d.b1_op == Some(ast::MmaB1Op::And) { "and" } else { "xor" };
    let mut acc = c.to_string();
    for (x, y) in a.iter().zip(b) {
        let v = ir.op(op, "i32", x, y);
        let v = ir.intrinsic("ctpop", "i32", &[&v]);
        acc = ir.op("add", "i32", &acc, &v);
    }
    acc
}

// ---------------------------------------------------------------- exact floating point dot products

#[derive(Copy, Clone, PartialEq)]
enum Specials {
    // infinities and NaNs as in IEEE 754
    Ieee,
    // e4m3: NaN is S.1111.111, no infinities
    E4m3,
    // fp6 and fp4: no infinities or NaNs
    None,
}

struct Format {
    mantissa: u32,
    exponent: u32,
    specials: Specials,
}

fn format(type_: ast::MmaType) -> Result<Format, TranslateError> {
    use ast::MmaType::*;
    let (mantissa, exponent, specials) = match type_ {
        F16 => (10, 5, Specials::Ieee),
        Bf16 => (7, 8, Specials::Ieee),
        Tf32 | F32 => (23, 8, Specials::Ieee),
        F64 => (52, 11, Specials::Ieee),
        E4m3 => (3, 4, Specials::E4m3),
        E5m2 => (2, 5, Specials::Ieee),
        E3m2 => (2, 3, Specials::None),
        E2m3 => (3, 2, Specials::None),
        E2m1 | E2m1x2 => (1, 2, Specials::None),
        _ => return Err(todo("floating point type")),
    };
    Ok(Format {
        mantissa,
        exponent,
        specials,
    })
}

/// A decoded floating point value or product: (-1)^sign * mantissa *
/// 2^exponent, of at most `width` significant bits; mantissa is 0 for zeros,
/// infinities and NaNs.
struct Term {
    sign: String,     // i1
    mantissa: String, // i64 or i128
    mantissa_type: &'static str,
    exponent: String, // i32
    width: u32,
    nan: String,  // i1
    inf: String,  // i1
    zero: String, // i1
}

fn decode(ir: &mut Ir, type_: ast::MmaType, raw: &str, raw_type: &str) -> Result<Term, TranslateError> {
    let f = format(type_)?;
    let x = ir.cast("zext", raw_type, raw, "i64");
    // the bits of the format in the container
    let x = match type_ {
        ast::MmaType::Tf32 => ir.op("and", "i64", &x, &(!0x1fffu64 & 0xffff_ffff).to_string()),
        ast::MmaType::E3m2 | ast::MmaType::E2m3 => ir.op("and", "i64", &x, "63"),
        // the central 4 bits of the 8-bit container
        ast::MmaType::E2m1 => {
            let x = ir.op("lshr", "i64", &x, "2");
            ir.op("and", "i64", &x, "15")
        }
        ast::MmaType::E2m1x2 => ir.op("and", "i64", &x, "15"),
        _ => x,
    };
    let frac = ir.op("and", "i64", &x, &((1u64 << f.mantissa) - 1).to_string());
    let e = ir.op("lshr", "i64", &x, &f.mantissa.to_string());
    let e_mask = (1u64 << f.exponent) - 1;
    let e = ir.op("and", "i64", &e, &e_mask.to_string());
    let s = ir.op("lshr", "i64", &x, &(f.mantissa + f.exponent).to_string());
    let sign = ir.cast("trunc", "i64", &s, "i1");
    let e_zero = ir.icmp("eq", "i64", &e, "0");
    let hidden = ir.op("or", "i64", &frac, &(1u64 << f.mantissa).to_string());
    let mantissa = ir.select(&e_zero, "i64", &frac, &hidden);
    let e_adj = ir.select(&e_zero, "i64", "1", &e);
    let e_adj = ir.cast("trunc", "i64", &e_adj, "i32");
    let bias = (1u32 << (f.exponent - 1)) - 1;
    let exponent = ir.op("sub", "i32", &e_adj, &(bias + f.mantissa).to_string());
    let (nan, inf) = match f.specials {
        Specials::Ieee => {
            let special = ir.icmp("eq", "i64", &e, &e_mask.to_string());
            let frac_zero = ir.icmp("eq", "i64", &frac, "0");
            let frac_nonzero = ir.icmp("ne", "i64", &frac, "0");
            (
                ir.op("and", "i1", &special, &frac_nonzero),
                ir.op("and", "i1", &special, &frac_zero),
            )
        }
        Specials::E4m3 => {
            let low = ir.op("and", "i64", &x, "127");
            (ir.icmp("eq", "i64", &low, "127"), "false".to_string())
        }
        Specials::None => ("false".to_string(), "false".to_string()),
    };
    let special = ir.op("or", "i1", &nan, &inf);
    let mantissa = ir.select(&special, "i64", "0", &mantissa);
    let zero0 = ir.icmp("eq", "i64", &mantissa, "0");
    let not_special = ir.op("xor", "i1", &special, "true");
    let zero = ir.op("and", "i1", &zero0, &not_special);
    Ok(Term {
        sign,
        mantissa,
        mantissa_type: "i64",
        exponent,
        width: f.mantissa + 1,
        nan,
        inf,
        zero,
    })
}

fn product(ir: &mut Ir, a: &Term, b: &Term) -> Term {
    let width = a.width + b.width;
    let ty = if width <= 64 { "i64" } else { "i128" };
    let x = ir.cast("zext", "i64", &a.mantissa, ty);
    let y = ir.cast("zext", "i64", &b.mantissa, ty);
    let mantissa = ir.op("mul", ty, &x, &y);
    let sign = ir.op("xor", "i1", &a.sign, &b.sign);
    let exponent = ir.op("add", "i32", &a.exponent, &b.exponent);
    // inf * 0 is NaN
    let inf_zero = ir.op("and", "i1", &a.inf, &b.zero);
    let zero_inf = ir.op("and", "i1", &a.zero, &b.inf);
    let nan = ir.op("or", "i1", &a.nan, &b.nan);
    let nan = ir.op("or", "i1", &nan, &inf_zero);
    let nan = ir.op("or", "i1", &nan, &zero_inf);
    let inf = ir.op("or", "i1", &a.inf, &b.inf);
    let not_nan = ir.op("xor", "i1", &nan, "true");
    let inf = ir.op("and", "i1", &inf, &not_nan);
    let zero = ir.op("or", "i1", &a.zero, &b.zero);
    let zero = ir.op("and", "i1", &zero, &not_nan);
    Term {
        sign,
        mantissa,
        mantissa_type: ty,
        exponent,
        width,
        nan,
        inf,
        zero,
    }
}

fn type_bits(ty: &str) -> u32 {
    ty[1..].parse().unwrap()
}

fn float_dot(ir: &mut Ir, d: &ast::MmaDetails, a: &[String], b: &[String], c: &str) -> Result<String, TranslateError> {
    let ab_ty = if register_bits(d.atype) == 64 { "i64" } else { "i32" };
    let c_ty = if register_bits(d.ctype) == 64 { "i64" } else { "i32" };
    let mut terms = vec![decode(ir, d.ctype, c, c_ty)?];
    for (x, y) in a.iter().zip(b) {
        let x = decode(ir, d.atype, x, ab_ty)?;
        let y = decode(ir, d.btype, y, ab_ty)?;
        terms.push(product(ir, &x, &y));
    }
    exact_sum(ir, &terms, d.dtype)
}

/// The sum of the terms, rounded once to nearest even into `type_`, as raw
/// bits in an i32 (i64 for `f64`).
fn exact_sum(ir: &mut Ir, terms: &[Term], type_: ast::MmaType) -> Result<String, TranslateError> {
    let f = format(type_)?;
    let wide = terms.iter().any(|t| t.mantissa_type == "i128");
    // The accumulator is made of 128-bit limbs (least significant first).
    let n: u32 = if wide { 256 } else { 128 };
    let limbs = (n / 128) as usize;
    // The window of the accumulator: n - 8 bits below the top of the largest
    // term (8 bits of headroom for the carries).
    let mut tmax = "-1073741824".to_string();
    for term in terms {
        let top = ir.op("add", "i32", &term.exponent, &term.width.to_string());
        let nonzero = ir.icmp("ne", term.mantissa_type, &term.mantissa, "0");
        let top = ir.select(&nonzero, "i32", &top, "-1073741824");
        tmax = ir.intrinsic("smax", "i32", &[&tmax, &top]);
    }
    let base = ir.op("sub", "i32", &tmax, &(n - 8).to_string());
    let mut acc = vec!["0".to_string(); limbs];
    for term in terms {
        let p = type_bits(term.mantissa_type);
        let sh = ir.op("sub", "i32", &term.exponent, &base);
        let positive = ir.icmp("sge", "i32", &sh, "0");
        // aligned left
        let left_amount = ir.select(&positive, "i32", &sh, "0");
        let left_amount = ir.intrinsic("umin", "i32", &[&left_amount, &(n - 1).to_string()]);
        let wide_m = ir.cast("zext", term.mantissa_type, &term.mantissa, "i128");
        let mut wide_m = vec![wide_m];
        wide_m.resize(limbs, "0".to_string());
        let left = shift_left(ir, &wide_m, &left_amount);
        // or right, the bits shifted out becoming a sticky bit
        let right_amount = ir.op("sub", "i32", "0", &sh);
        let right_amount = ir.select(&positive, "i32", "0", &right_amount);
        let all_out = ir.icmp("uge", "i32", &right_amount, &p.to_string());
        let right_amount = ir.intrinsic("umin", "i32", &[&right_amount, &(p - 1).to_string()]);
        let right_amount = ir.cast("zext", "i32", &right_amount, term.mantissa_type);
        let right = ir.op("lshr", term.mantissa_type, &term.mantissa, &right_amount);
        let right = ir.select(&all_out, term.mantissa_type, "0", &right);
        let shifted_back = ir.op("shl", term.mantissa_type, &right, &right_amount);
        let lost = ir.icmp("ne", term.mantissa_type, &shifted_back, &term.mantissa);
        let right = ir.cast("zext", term.mantissa_type, &right, "i128");
        let lost = ir.cast("zext", "i1", &lost, "i128");
        let right = ir.op("or", "i128", &right, &lost);
        let v = (0..limbs)
            .map(|j| {
                let r = if j == 0 { right.as_str() } else { "0" };
                ir.select(&positive, "i128", &left[j], r)
            })
            .collect::<Vec<_>>();
        let sum = add_limbs(ir, &acc, &v, false);
        let difference = add_limbs(ir, &acc, &v, true);
        acc = (0..limbs)
            .map(|j| ir.select(&term.sign, "i128", &difference[j], &sum[j]))
            .collect();
    }
    // normalize to 64 bits and a sticky bit, then round
    let negative = ir.icmp("slt", "i128", &acc[limbs - 1], "0");
    let zeros = vec!["0".to_string(); limbs];
    let minus = add_limbs(ir, &zeros, &acc, true);
    let magnitude = (0..limbs)
        .map(|j| ir.select(&negative, "i128", &minus[j], &acc[j]))
        .collect::<Vec<_>>();
    ir.declarations
        .insert("declare i128 @llvm.ctlz.i128(i128, i1)".to_string());
    // leading zeros of the whole accumulator
    let mut lz = "0".to_string();
    let mut all_zero = "true".to_string();
    for j in (0..limbs).rev() {
        let z = ir.def(&format!("call i128 @llvm.ctlz.i128(i128 {}, i1 false)", magnitude[j]));
        let z = ir.cast("trunc", "i128", &z, "i32");
        let below = ir.op("add", "i32", &(128 * (limbs - 1 - j)).to_string(), &z);
        lz = ir.select(&all_zero, "i32", &below, &lz);
        let limb_zero = ir.icmp("eq", "i128", &magnitude[j], "0");
        all_zero = ir.op("and", "i1", &all_zero, &limb_zero);
    }
    let lz = ir.intrinsic("umin", "i32", &[&lz, &(n - 1).to_string()]);
    let normalized = shift_left(ir, &magnitude, &lz);
    let high = &normalized[limbs - 1];
    let top = ir.op("lshr", "i128", high, "64");
    let top = ir.cast("trunc", "i128", &top, "i64");
    let low = ir.cast("trunc", "i128", high, "i64");
    let mut sticky = ir.icmp("ne", "i64", &low, "0");
    for limb in &normalized[..limbs - 1] {
        let nonzero = ir.icmp("ne", "i128", limb, "0");
        sticky = ir.op("or", "i1", &sticky, &nonzero);
    }
    let e = ir.op("add", "i32", &base, &(n - 64).to_string());
    let e = ir.op("sub", "i32", &e, &lz);
    // an exact zero is -0 only if all the terms are -0
    let mut negative_zero = "true".to_string();
    let mut nan = "false".to_string();
    let mut plus_inf = "false".to_string();
    let mut minus_inf = "false".to_string();
    for term in terms {
        let nz = ir.op("and", "i1", &term.zero, &term.sign);
        negative_zero = ir.op("and", "i1", &negative_zero, &nz);
        nan = ir.op("or", "i1", &nan, &term.nan);
        let positive = ir.op("xor", "i1", &term.sign, "true");
        let pi = ir.op("and", "i1", &term.inf, &positive);
        let mi = ir.op("and", "i1", &term.inf, &term.sign);
        plus_inf = ir.op("or", "i1", &plus_inf, &pi);
        minus_inf = ir.op("or", "i1", &minus_inf, &mi);
    }
    let is_zero = all_zero;
    let sign = ir.select(&is_zero, "i1", &negative_zero, &negative);
    let bits = ir.def(&format!(
        "call i64 @__zluda_ptx_impl_agx_round_pack(i1 {sign}, i64 {top}, i1 {sticky}, i32 {e}, i32 {}, i32 {})",
        f.mantissa, f.exponent
    ));
    let both_inf = ir.op("and", "i1", &plus_inf, &minus_inf);
    let nan = ir.op("or", "i1", &nan, &both_inf);
    let inf = ((1u64 << f.exponent) - 1) << f.mantissa;
    let sign_bit = 1u64 << (f.mantissa + f.exponent);
    let result = ir.select(&minus_inf, "i64", &(inf | sign_bit).to_string(), &bits);
    let result = ir.select(&plus_inf, "i64", &inf.to_string(), &result);
    let result = ir.select(&nan, "i64", &(sign_bit - 1).to_string(), &result);
    Ok(if type_ == ast::MmaType::F64 {
        result
    } else {
        ir.cast("trunc", "i64", &result, "i32")
    })
}

// A number made of 128-bit limbs shifted left by `amount` (an i32 below the
// width): each limb is made of the parts of the limbs at or below it.
fn shift_left(ir: &mut Ir, limbs: &[String], amount: &str) -> Vec<String> {
    (0..limbs.len())
        .map(|j| {
            let mut result = "0".to_string();
            for (i, limb) in limbs.iter().enumerate().take(j + 1) {
                // limb i lands at bit 128 * (i - j) + amount of limb j
                let d = ir.op("sub", "i32", amount, &(128 * (j - i)).to_string());
                let in_left = ir.icmp("ult", "i32", &d, "128");
                let left_amount = ir.intrinsic("umin", "i32", &[&d, "127"]);
                let left_amount = ir.cast("zext", "i32", &left_amount, "i128");
                let left = ir.op("shl", "i128", limb, &left_amount);
                // the high bits of limb i - 1 ... come in from below
                let r = ir.op("sub", "i32", "0", &d);
                let in_right = ir.icmp("ult", "i32", &r, "128");
                let right_amount = ir.intrinsic("umin", "i32", &[&r, "127"]);
                let right_amount = ir.cast("zext", "i32", &right_amount, "i128");
                let right = ir.op("lshr", "i128", limb, &right_amount);
                let right = ir.select(&in_right, "i128", &right, "0");
                let part = ir.select(&in_left, "i128", &left, &right);
                result = ir.op("or", "i128", &result, &part);
            }
            result
        })
        .collect()
}

// a + b (or a - b) of numbers made of 128-bit limbs
fn add_limbs(ir: &mut Ir, a: &[String], b: &[String], subtract: bool) -> Vec<String> {
    let mut carry = "false".to_string();
    let mut result = Vec::new();
    for (x, y) in a.iter().zip(b) {
        let op = if subtract { "sub" } else { "add" };
        let r = ir.op(op, "i128", x, y);
        let c = ir.cast("zext", "i1", &carry, "i128");
        let r2 = ir.op(op, "i128", &r, &c);
        // carry (borrow) out of x op y, then of op c
        let out1 = if subtract {
            ir.icmp("ult", "i128", x, y)
        } else {
            ir.icmp("ult", "i128", &r, x)
        };
        let out2 = if subtract {
            ir.icmp("ult", "i128", &r, &c)
        } else {
            ir.icmp("ult", "i128", &r2, &r)
        };
        carry = ir.op("or", "i1", &out1, &out2);
        result.push(r2);
    }
    result
}

// ---------------------------------------------------------------- wmma

/// The `mma.sync` tiles of a `wmma.mma`: 16x8 (8x8 for 8-row matrices) by
/// the whole k.
struct Tiles {
    tile: ast::MmaDetails,
    rows: u32,
    columns: u32,
}

fn tiles(d: &ast::MmaDetails) -> Tiles {
    let tile_m = if d.m >= 16 { 16 } else { 8 };
    Tiles {
        tile: ast::MmaDetails {
            m: tile_m,
            n: 8,
            ..*d
        },
        rows: d.m / tile_m,
        columns: d.n / 8,
    }
}

impl Tiles {
    fn count(&self, matrix: ast::MmaMatrix) -> u32 {
        match matrix {
            ast::MmaMatrix::A => self.rows,
            ast::MmaMatrix::B => self.columns,
            _ => self.rows * self.columns,
        }
    }

    // (row, column) offset of tile `index` of a matrix
    fn offset(&self, matrix: ast::MmaMatrix, index: u32) -> (u32, u32) {
        match matrix {
            ast::MmaMatrix::A => (index * self.tile.m, 0),
            ast::MmaMatrix::B => (0, index * 8),
            _ => ((index / self.columns) * self.tile.m, (index % self.columns) * 8),
        }
    }
}

fn wmma_mma(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::MmaDetails,
    a: &[String],
    b: &[String],
    c: &[String],
) -> Result<Vec<String>, TranslateError> {
    let tiles = tiles(d);
    let tile = &tiles.tile;
    let (ra, rb, rc) = (
        tile.mma_registers(ast::MmaMatrix::A) as usize,
        tile.mma_registers(ast::MmaMatrix::B) as usize,
        tile.mma_registers(ast::MmaMatrix::C) as usize,
    );
    let mut result = Vec::new();
    for i in 0..tiles.rows as usize {
        for j in 0..tiles.columns as usize {
            let index = i * tiles.columns as usize + j;
            let part = |regs: &[String], n: usize, k: usize| -> Result<Vec<String>, TranslateError> {
                regs.get(k * n..(k + 1) * n)
                    .map(|r| r.to_vec())
                    .ok_or_else(|| todo("wmma fragment size"))
            };
            let tile_d = mma_tile(
                ir,
                lane,
                tile,
                &part(a, ra, i)?,
                &part(b, rb, j)?,
                &part(c, rc, index)?,
                None,
            )?;
            result.extend(tile_d);
        }
    }
    Ok(result)
}

// For each register of a wmma fragment, the (row, column) as linear
// functions of (g, t) of its elements: (rg, rt, row, cg, ct, column).
fn wmma_elements(
    d: &ast::WmmaLoadStoreDetails,
) -> Result<Vec<Vec<(u32, u32, u32, u32, u32, u32)>>, TranslateError> {
    let mma = d.mma();
    let tiles = tiles(&mma);
    let tile = &tiles.tile;
    let matrix = d.matrix;
    let layout_matrix = if matrix == ast::MmaMatrix::D { ast::MmaMatrix::C } else { matrix };
    let bits = d.type_.bits();
    let (rows, columns) = tile.matrix_size(layout_matrix);
    let count = rows * columns / 32;
    let layout = Layout::new(layout_matrix, tile.m, tile.k, bits, count)?;
    let per = register_bits(d.type_) / bits;
    let tile_registers = tile.mma_registers(layout_matrix) as u32;
    let total = tile_registers * tiles.count(layout_matrix);
    let registers = mma.wmma_registers(matrix) as u32;
    if registers % total != 0 {
        return Err(todo("wmma fragment size"));
    }
    Ok((0..registers)
        .map(|r| {
            let r = r % total;
            let (index, local) = (r / tile_registers, r % tile_registers);
            let (row0, col0) = tiles.offset(layout_matrix, index);
            (0..per)
                .map(|s| {
                    let i = (local * per + s) as usize;
                    (
                        layout.rg,
                        layout.rt,
                        row0 + layout.row[i],
                        layout.cg,
                        layout.ct,
                        col0 + layout.col[i],
                    )
                })
                .collect()
        })
        .collect())
}

// The index of an element in memory: row * stride + column (row major) or
// column * stride + row (column major), as an i64.
fn element_index(
    ir: &mut Ir,
    lane: &Lane,
    layout: ast::MatrixLayout,
    stride: &str,
    (rg, rt, row, cg, ct, col): (u32, u32, u32, u32, u32, u32),
) -> String {
    let r = ir.linear(rg, &lane.g, rt, &lane.t, row);
    let c = ir.linear(cg, &lane.g, ct, &lane.t, col);
    let (slow, fast) = match layout {
        ast::MatrixLayout::Row => (r, c),
        ast::MatrixLayout::Col => (c, r),
    };
    let slow = ir.cast("zext", "i32", &slow, "i64");
    let fast = ir.cast("zext", "i32", &fast, "i64");
    let stride = ir.cast("zext", "i32", stride, "i64");
    let x = ir.op("mul", "i64", &slow, &stride);
    ir.op("add", "i64", &x, &fast)
}

fn contiguous(layout: ast::MatrixLayout, elements: &[(u32, u32, u32, u32, u32, u32)]) -> bool {
    elements.windows(2).all(|w| {
        let (a, b) = (w[0], w[1]);
        match layout {
            ast::MatrixLayout::Row => b.2 == a.2 && b.5 == a.5 + 1,
            ast::MatrixLayout::Col => b.5 == a.5 && b.2 == a.2 + 1,
        }
    })
}

fn wmma_load(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::WmmaLoadStoreDetails,
    p: &str,
    ptr_type: &str,
    stride: &str,
) -> Result<Vec<String>, TranslateError> {
    let base = pointer_bits(ir, p, ptr_type);
    let bits = d.type_.bits();
    let reg_bits = register_bits(d.type_);
    let reg_ty = if reg_bits == 64 { "i64" } else { "i32" };
    let mut regs = Vec::new();
    for elements in wmma_elements(d)? {
        let index = element_index(ir, lane, d.layout, stride, elements[0]);
        if elements.len() == 1 || contiguous(d.layout, &elements) {
            // the whole register at once (wmma requires aligned fragments)
            let bit = ir.op("mul", "i64", &index, &bits.to_string());
            let byte = ir.op("lshr", "i64", &bit, "3");
            let a = ir.address(&base, &byte, ptr_type);
            regs.push(ir.load(reg_ty, &a, ptr_type, reg_bits / 8));
            continue;
        }
        let mut value = "0".to_string();
        for (s, e) in elements.iter().enumerate() {
            let index = element_index(ir, lane, d.layout, stride, *e);
            let bit = ir.op("mul", "i64", &index, &bits.to_string());
            let byte = ir.op("lshr", "i64", &bit, "3");
            let a = ir.address(&base, &byte, ptr_type);
            let x = if bits >= 8 {
                let ty = format!("i{bits}");
                let x = ir.load(&ty, &a, ptr_type, bits / 8);
                ir.cast("zext", &ty, &x, reg_ty)
            } else {
                let x = ir.load("i8", &a, ptr_type, 1);
                let x = ir.cast("zext", "i8", &x, reg_ty);
                let in_byte = ir.op("and", "i64", &bit, "7");
                let in_byte = ir.cast("trunc", "i64", &in_byte, reg_ty);
                let x = ir.op("lshr", reg_ty, &x, &in_byte);
                ir.op("and", reg_ty, &x, &((1u64 << bits) - 1).to_string())
            };
            let x = ir.op("shl", reg_ty, &x, &(s as u32 * bits).to_string());
            value = ir.op("or", reg_ty, &value, &x);
        }
        regs.push(value);
    }
    Ok(regs)
}

fn wmma_store(
    ir: &mut Ir,
    lane: &Lane,
    d: &ast::WmmaLoadStoreDetails,
    p: &str,
    ptr_type: &str,
    regs: &[String],
    stride: &str,
) -> Result<(), TranslateError> {
    let base = pointer_bits(ir, p, ptr_type);
    let bits = d.type_.bits();
    if bits < 8 {
        return Err(todo("wmma.store type"));
    }
    let reg_bits = register_bits(d.type_);
    let reg_ty = if reg_bits == 64 { "i64" } else { "i32" };
    let ty = format!("i{bits}");
    for (r, elements) in wmma_elements(d)?.iter().enumerate() {
        let reg = regs.get(r).ok_or_else(|| todo("wmma fragment size"))?;
        for (s, e) in elements.iter().enumerate() {
            let index = element_index(ir, lane, d.layout, stride, *e);
            let byte = ir.op("mul", "i64", &index, &(bits / 8).to_string());
            let a = ir.address(&base, &byte, ptr_type);
            let x = ir.op("lshr", reg_ty, reg, &(s as u32 * bits).to_string());
            let x = ir.cast("trunc", reg_ty, &x, &ty);
            ir.store(&ty, &x, &a, ptr_type, bits / 8);
        }
    }
    Ok(())
}
